<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\CmsContent; use Moves\Support\CmsView as V;
$post = $id ? CmsContent::post($id) : null;
if ($id && $post === null) { http_response_code(404); echo V::empty('Conteúdo não encontrado.'); return; }
$p = $post ?? []; $cats = ['' => 'Sem categoria']; foreach (CmsContent::categories() as $c) { $cats[$c['id']] = $c['title']; } ?>
<div class="cms-grid-2"><form class="cms-card" method="post" action="/acao/post-save"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($id ?? 0) ?: '' ?>">
<?= V::field('Título', 'title', $p['title'] ?? '', ['required' => true]) ?><div class="cms-form-grid"><?= V::field('Tipo', 'post_type', $p['post_type'] ?? (V::queryString('type') ?: 'article'), ['type' => 'select', 'choices' => CmsContent::POST_TYPES]) ?><?= V::field('Categoria', 'category', $p['category'] ?? '', ['type' => 'select', 'choices' => $cats]) ?></div>
<?= V::field('Endereço', 'uri', $p['uri'] ?? '') ?><?= V::field('Resumo', 'subtitle', $p['subtitle'] ?? '', ['type' => 'textarea', 'rows' => 2]) ?><?= V::field('Conteúdo', 'content', $p['content'] ?? '', ['type' => 'textarea', 'rows' => 14, 'editor' => true, 'help' => 'Scripts, estilos e atributos perigosos são removidos ao salvar.']) ?>
<?= V::mediaField('Imagem de capa', 'cover', $p['cover'] ?? null) ?><?php $this->insert('components/seo-fields', ['seo' => $p]); ?><button class="cms-btn-primary">Salvar</button></form>
<aside><div class="cms-card"><h2>Publicação</h2><?php if ($post): ?><p><?= V::badge($post['status'], $post['status'] === 'published' ? 'Publicado' : 'Rascunho') ?></p><div class="cms-actions"><?php if (CmsAuth::can($admin, 'content.publish')): ?><?= $post['status'] === 'published' ? V::actionButton('post-publish', 'Despublicar', ['id' => $id, 'publish' => 0]) : V::actionButton('post-publish', 'Publicar', ['id' => $id, 'publish' => 1], 'cms-btn-primary') ?><?php endif; ?><?= V::actionButton('post-delete', 'Excluir', ['id' => $id], 'cms-btn-danger', 'Excluir este conteúdo?') ?></div><?php else: ?><p>Todo conteúdo novo começa como rascunho.</p><?php endif; ?></div></aside></div>
